package io.odysz.semantic.ext;

import java.util.List;

import io.odysz.anson.Anson;

/**
 * Test data of {@link SemanticTreeTest}, loaded from src/test/res/stree/stree-cases.json,
 * which is generated by src/test/res/stree/gen.py.
 *
 * <p>Tree lines: "nid parent sort fullpath indents", in fullpath order; '-' for null / empty.</p>
 *
 * @since 1.5.20
 */
public class StreeCases extends Anson {
	String table;

	/** tree semantics, see {@link io.odysz.semantic.DA.DatasetCfg.TreeSemantics} */
	String stree;

	/** drop / create table */
	List<String> ddl;

	/** insert statements of the fixture */
	List<String> fixture;

	/** expected tree of the fixture */
	List<String> fixtureTree;

	List<StreeStep> steps;

	public StreeCases() { }
}
